//! Golden vectors generated by the frozen PyCINRAD gpf.py and real Matplotlib.
#![allow(clippy::unwrap_used)]
use rustcinrad::{FieldId, visualize::Palette};

#[test]
fn lookup_colors_match_matplotlib_normalization_and_colormaps() {
    for line in include_str!("data/matplotlib_colors.csv").lines().skip(1) {
        let columns: Vec<_> = line.split(',').collect();
        let field: FieldId = columns[0].parse().unwrap();
        let value: f32 = columns[1].parse().unwrap();
        let expected: [u8; 3] = std::array::from_fn(|i| columns[i + 2].parse().unwrap());
        let actual = Palette::for_field(field).color(value, field.is_categorical());
        assert!(actual.iter().zip(expected).all(|(&a, b)| a.abs_diff(b) <= 1), "{line}: {actual:?}");
    }
}
